package geometries.api;

import primitives.Point;
import primitives.Ray;
import primitives.Vector;

/**
 * Abstract base class for all geometric bodies in the scene.
 * Every geometry must be able to return its normal vector at a given point.
 *
 * @author David &amp; Yehuda
 */
public abstract class Geometry extends Intersectable {

    /**
     * Constructs a geometry. This constructor is empty because the base class does not have any fields to initialize.
     */
    public Geometry() {
        // No initialization needed for the base class
    }

    /**
     * Returns the normal vector to the geometry at the given point.
     *
     * @param point a point on the surface of the geometry
     * @return the normal vector at the given point
     */
    public abstract Vector getNormal(Point point);

}

package geometries.api;

import primitives.Point;
import primitives.Ray;
import primitives.Vector;

/**
 * Abstract base class for all geometric bodies in the scene.
 * Every geometry must be able to return its normal vector at a given point.
 *
 * @author David &amp; Yehuda
 */
public abstract class Geometry extends Intersectable {

    /**
     * Returns the normal vector to the geometry at the given point.
     *
     * @param point a point on the surface of the geometry
     * @return the normal vector at the given point
     */
    public abstract Vector getNormal(Point point);

}

package geometries.impl;

import java.util.List;

import geometries.api.Geometry;
import primitives.Point;
import primitives.Ray;
import primitives.Vector;

/**
 * Represents a plane in 3D space, defined by a point and a normal vector.
 *
 * @author David &amp; Yehuda
 */
public class Plane extends Geometry {

    /**
     * A point on the plane.
     */
    private final Point _point;

    /**
     * The normalized normal vector of the plane.
     */
    private final Vector _normal;

    /**
     * Constructs a plane from three points.
     * At this stage, one point is stored as a reference and the normal
     * is intentionally initialized to {@code null}.
     *
     * @param p1 first point on the plane
     * @param p2 second point on the plane
     * @param p3 third point on the plane
     */
    public Plane(Point p1, Point p2, Point p3) {
        _point = p1;

        Vector v1 = p2.subtract(p1);
        Vector v2 = p3.subtract(p1);

        _normal = v1.crossProduct(v2).normalize();
    }

    /**
     * Constructs a plane from a point and a normal vector.
     * The normal vector is normalized before being stored.
     *
     * @param point  a point on the plane
     * @param normal the normal vector of the plane (need not be normalized)
     */
    public Plane(Point point, Vector normal) {
        _point = point;
        _normal = normal.normalize();
    }

    @Override
    public Vector getNormal(Point point) {
        return _normal;
    }

    @Override
    public List<Point> findIntersections(Ray ray) {
        return null;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Plane other = (Plane) obj;
        return _point.equals(other._point) && _normal.equals(other._normal);
    }

    @Override
    public int hashCode() {
        return 31 * _point.hashCode() + _normal.hashCode();
    }

    @Override
    public String toString() {
        return "Plane{point=" + _point + ", normal=" + _normal + "}";
    }
}

package geometries.impl;

import java.util.List;

import geometries.api.Geometry;
import primitives.Point;
import primitives.Ray;
import primitives.Vector;

/**
 * Represents a plane in 3D space, defined by a point and a normal vector.
 *
 * @author David &amp; Yehuda
 */
public class Plane extends Geometry {

    /**
     * A point on the plane.
     */
    private final Point _point;

    /**
     * The normalized normal vector of the plane.
     */
    private final Vector _normal;

    /**
     * Constructs a plane from three points.
     * The plane stores a reference point and computes the normalized normal vector
     * from the cross product of two edge vectors formed by the three points.
     *
     * @param p1 first point on the plane
     * @param p2 second point on the plane
     * @param p3 third point on the plane
     */
    public Plane(Point p1, Point p2, Point p3) {
        _point = p1;

        Vector v1 = p2.subtract(p1);
        Vector v2 = p3.subtract(p1);

        _normal = v1.crossProduct(v2).normalize();
    }

    /**
     * Constructs a plane from a point and a normal vector.
     * The normal vector is normalized before being stored.
     *
     * @param point  a point on the plane
     * @param normal the normal vector of the plane (need not be normalized)
     */
    public Plane(Point point, Vector normal) {
        _point = point;
        _normal = normal.normalize();
    }

    @Override
    public Vector getNormal(Point point) {
        return _normal;
    }

    @Override
    public List<Point> findIntersections(Ray ray) {
        return null;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Plane other = (Plane) obj;
        return _point.equals(other._point) && _normal.equals(other._normal);
    }

    @Override
    public int hashCode() {
        return 31 * _point.hashCode() + _normal.hashCode();
    }

    @Override
    public String toString() {
        return "Plane{point=" + _point + ", normal=" + _normal + "}";
    }
}

package geometries.impl;

import geometries.api.Geometry;

/**
 * Abstract base class for all radial geometric bodies (bodies defined by a radius).
 *
 * @author David &amp; Yehuda
 */
public abstract class RadialGeometry extends Geometry {

    /**
     * The radius of the geometry.
     */
    protected final double _radius;

    /**
     * The squared radius of the geometry.
     */
    protected final double _radiusSquared;

    /**
     * Constructs a radial geometry with the given radius.
     *
     * @param radius the radius of the geometry
     */
    public RadialGeometry(double radius) {
        _radius = radius;
        _radiusSquared = radius * radius;
    }
}

package geometries.impl;

import geometries.api.Geometry;

/**
 * Abstract base class for all radial geometric bodies (bodies defined by a radius).
 *
 * @author David &amp; Yehuda
 */
public abstract class RadialGeometry extends Geometry {

    /**
     * The radius of the geometry.
     */
    protected final double _radius;

    /**
     * The squared radius of the geometry (pre-computed for optimization).
     */
    protected final double _radiusSquared;

    /**
     * Constructs a radial geometry with the given radius.
     *
     * @param radius the radius of the geometry
     */
    public RadialGeometry(double radius) {
        _radius = radius;
        _radiusSquared = radius * radius;
    }
}

package geometries.impl;

import java.util.List;

import primitives.Point;
import primitives.Ray;
import primitives.Vector;
import static primitives.Util.alignZero;

/**
 * Represents a sphere in 3D space, defined by a center point and a radius.
 *
 * @author David &amp; Yehuda
 */
public class Sphere extends RadialGeometry {

    /**
     * Center point of the sphere.
     */
    private final Point _center;

    /**
     * Constructs a sphere from a center point and radius.
     *
     * @param center the center point
     * @param radius the sphere radius
     */
    public Sphere(Point center, double radius) {
        super(radius);
        _center = center;
    }

    private final Point getPoint(double t) {
        return Point point.add(_center, t);
    }

    @Override
    public Vector getNormal(Point point) {
        return point.subtract(_center).normalize();
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Sphere other = (Sphere) obj;
        return Double.compare(_radius, other._radius) == 0 && _center.equals(other._center);
    }

    @Override
    public List<Point> findIntersections(Ray ray) {
        Point p0 = ray.origin();
        Vector v = ray.direction();

        Vector l;
        try {
            l = _center.subtract(p0);
        } catch (IllegalArgumentException ignore) {
            // אם ראשית הקרן היא בדיוק מרכז הכדור
            return List.of(ray.origin().add(_radius));
        }

        double tm = alignZero(l.dotProduct(v));

        // חישוב המרחק בריבוע ממרכז הכדור לקו הקרן (d^2)
        double dSquared = alignZero(l.lengthSquared() - tm * tm);
        double rSquared = _radius * _radius;

        // אם המרחק גדול מהרדיוס, אין חיתוך
        if (dSquared >= rSquared) return null;

        // th הוא המרחק מנקודת ההיטל לנקודות החיתוך על פני הכדור
        double th = alignZero(Math.sqrt(rSquared - dSquared));

        List<Point> intersections = new ArrayList<>(2);

        if (t1 > 0) intersections.add(ray.getPoint(t1));
        if (t2 > 0) intersections.add(ray.getPoint(t2));

        return intersections.isEmpty() ? null : intersections;

        return null;

    }

    @Override
    public int hashCode() {
        return 31 * Double.hashCode(_radius) + _center.hashCode();
    }

    @Override
    public String toString() {
        return "Sphere{center=" + _center + ", radius=" + _radius + "}";
    }
}

package geometries.impl;

import java.util.ArrayList;
import java.util.List;

import primitives.Point;
import primitives.Ray;
import primitives.Vector;
import static primitives.Util.alignZero;

/**
 * Represents a sphere in 3D space, defined by a center point and a radius.
 *
 * @author David &amp; Yehuda
 */
public class Sphere extends RadialGeometry {

    /**
     * Center point of the sphere.
     */
    private final Point _center;

    /**
     * Constructs a sphere from a center point and radius.
     *
     * @param center the center point
     * @param radius the sphere radius
     */
    public Sphere(Point center, double radius) {
        super(radius);
        _center = center;
    }

    @Override
    public Vector getNormal(Point point) {
        return point.subtract(_center).normalize();
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Sphere other = (Sphere) obj;
        return Double.compare(_radius, other._radius) == 0 && _center.equals(other._center);
    }

    @Override
    public List<Point> findIntersections(Ray ray) {
        Point p0 = ray.origin();
        Vector v = ray.direction();

        Vector l;
        try {
            l = _center.subtract(p0);
        } catch (IllegalArgumentException ignore) {
            // Ray origin is exactly at the sphere center; one intersection at distance _radius
            return List.of(ray.getPoint(_radius));
        }

        double tm = alignZero(l.dotProduct(v));

        // Squared distance from sphere center to the ray line (d^2)
        double dSquared = alignZero(l.lengthSquared() - tm * tm);
        double rSquared = _radius * _radius;

        // If the ray misses the sphere entirely, no intersections
        if (dSquared >= rSquared) return null;

        // th is the half-chord length inside the sphere
        double th = alignZero(Math.sqrt(rSquared - dSquared));

        double t1 = alignZero(tm - th);
        double t2 = alignZero(tm + th);

        List<Point> intersections = new ArrayList<>(2);

        if (t1 > 0) intersections.add(ray.getPoint(t1));
        if (t2 > 0) intersections.add(ray.getPoint(t2));

        return intersections.isEmpty() ? null : intersections;
    }

    @Override
    public int hashCode() {
        return 31 * Double.hashCode(_radius) + _center.hashCode();
    }

    @Override
    public String toString() {
        return "Sphere{center=" + _center + ", radius=" + _radius + "}";
    }
}
